// Lerp two colours
COLORREF lerpCol(COLORREF a,COLORREF b,float t){
    t=easeOut(t);
    return RGB(
        (int)(GetRValue(a)+(GetRValue(b)-GetRValue(a))*t),
        (int)(GetGValue(a)+(GetGValue(b)-GetGValue(a))*t),
        (int)(GetBValue(a)+(GetBValue(b)-GetBValue(a))*t)
    );
}

